        // Create-style tooltips: summary always, conditionN/behaviourN on Shift, controlN/actionN on Ctrl
        lang("block.create_new_era.brass_computer.tooltip.summary", "Runs the _Lua_ programs you write in its editor. They work redstone and, through _data ports_ and _cables_, any machine you wire up.");
        lang("block.create_new_era.brass_computer.tooltip.condition1", "When rotated");
        lang("block.create_new_era.brass_computer.tooltip.behaviour1", "Needs a _shaft_ in its back. Faster rotation means faster programs. With no rotation they _pause_ and pick up where they left off.");
        lang("block.create_new_era.brass_computer.tooltip.condition2", "Redstone");
        lang("block.create_new_era.brass_computer.tooltip.behaviour2", "Each face is a side: front, back, left, right, top, bottom. _redstone.getInput_ reads them, _redstone.setOutput_ powers them.");
        lang("block.create_new_era.brass_computer.tooltip.condition3", "When the world loads");
        lang("block.create_new_era.brass_computer.tooltip.behaviour3", "A program that was running _starts over_ from the top.");
        lang("block.create_new_era.brass_computer.tooltip.control1", "When R-Clicked");
        lang("block.create_new_era.brass_computer.tooltip.action1", "Opens the _editor_. _Ctrl+R_ runs the program, _Ctrl+T_ stops it.");
        lang("block.create_new_era.brass_computer.tooltip.control2", "When Wrenched");
        lang("block.create_new_era.brass_computer.tooltip.action2", "Turns it round. Its sides are named from the front, so they turn with it.");
        lang("block.create_new_era.brass_screen.tooltip.summary", "A display of _flip dots_ that turn over to show a new colour. Next to each other, screens become one big pane.");
        lang("block.create_new_era.brass_screen.tooltip.condition1", "Next to another screen");
