        lang("block.create_new_era.brass_screen.tooltip.condition2", "On the bus");
        lang("block.create_new_era.brass_screen.tooltip.behaviour2", "Write a layout in a _.screen_ file and show it with _show(\"name\")_. Change parts with _set(id, value)_, hear buttons with _onClick_.");
        lang("block.create_new_era.brass_screen.tooltip.control1", "When Wrenched");
        lang("block.create_new_era.brass_screen.tooltip.action1", "Turns it. It joins whichever screens it lines up with afterwards.");
