        lang("block.create_new_era.panel_lamp.tooltip.condition2", "On the bus");
        lang("block.create_new_era.panel_lamp.tooltip.behaviour2", "_set(\"green\")_ lights it, _set(\"off\")_ puts it out, _setBrightness(n)_ dims it.");
        lang("block.create_new_era.nixie_digit.tooltip.summary", "Create's _nixie tube_ on a panel, glowing any letter, number or symbol. Tubes in a row read as one display.");
