        lang("block.create_new_era.panel_gauge.tooltip.behaviour1", "Goes on whatever face you click: floors, walls or ceilings. A few of them make a _control desk_.");
        lang("block.create_new_era.panel_gauge.tooltip.condition2", "On the bus");
